const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  // `seed` is an optional object literal that is JSON.stringify'd into the new window's
  // localStorage at the STORAGE_KEY before app.js runs, so data-table steps can provision
  // state without a second load cycle.
  // `extraStorage` is an optional object of extra key-value pairs to write into localStorage.
  loadApp(seed, extraStorage) {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();

    // Seed localStorage before the app initialises.
    if (seed !== undefined) {
      this.window.localStorage.setItem('todos-vanillajs', JSON.stringify(seed));
    }
    // Extra localStorage entries (e.g. persisted filter state).
    if (extraStorage !== undefined) {
      for (const [key, value] of Object.entries(extraStorage)) {
        this.window.localStorage.setItem(key, value);
      }
    }

    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

const { Given, When, Then, Before } = require('@cucumber/cucumber');
const assert = require('node:assert');

// -------------------------------------------------------------------------
// Background steps
// -------------------------------------------------------------------------

Given('the app is loaded', function () {
  // Already loaded by world.js Before hook
  assert.ok(this.document, 'app document should exist');
});

Given('there are no saved todos', function () {
  this.loadApp([]);
});

Given('the new-todo input is focused', function () {
  // The new-todo input should already be focused via autofocus
  // Focus it explicitly for the test
  const input = this.document.querySelector('.new-todo');
  input.focus();
});

// -------------------------------------------------------------------------
// Data table step - "the following todos exist:"
// -------------------------------------------------------------------------

Given('the following todos exist:', function (dataTable) {
  const rows = dataTable.hashes();
  const todos = rows.map(function (r) {
    return {
      id: Date.now() + Math.random().toString(36).substr(2, 9),
      title: r.title,
      completed: false
    };
  });
  this.loadApp(todos);
});

// -------------------------------------------------------------------------
// Completion steps
// -------------------------------------------------------------------------

Given('the {string} todo is completed', function (title) {
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  for (let i = 0; i < stored.length; i++) {
    if (stored[i].title === title) {
      stored[i].completed = true;
    }
  }
  this.loadApp(stored);
});

Given('all todos are completed', function () {
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  for (let i = 0; i < stored.length; i++) {
    stored[i].completed = true;
  }
  this.loadApp(stored);
});

// -------------------------------------------------------------------------
// Action steps (When)
// -------------------------------------------------------------------------

When('I type {string} into the new-todo input', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  // Dispatch input event so app can listen if needed
  const evt = new this.window.Event('input', { bubbles: true });
  input.dispatchEvent(evt);
});

When('I press Enter', function () {
  // Check if an edit input exists and the app is in editing mode
  const inEdit = this.document.querySelector('.todo-list li.editing');
  const input = inEdit
    ? this.document.querySelector('.edit')
    : this.document.querySelector('.new-todo');
  const evt = new this.window.KeyboardEvent('keydown', {
    key: 'Enter',
    keyCode: 13,
    which: 13,
    bubbles: true
  });
  input.dispatchEvent(evt);
});

When('I press Escape', function () {
  const editInput = this.document.querySelector('.edit');
  if (!editInput) return;
  const evt = new this.window.KeyboardEvent('keydown', {
    key: 'Escape',
    keyCode: 27,
    which: 27,
    bubbles: true
  });
  editInput.dispatchEvent(evt);
});

When('I click the toggle checkbox for {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) {
      const toggle = items[i].querySelector('.toggle');
      toggle.click();
      return;
    }
  }
  assert.fail('Could not find todo item with title: ' + title);
});

When('I click the destroy button for {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) {
      const destroy = items[i].querySelector('.destroy');
      destroy.click();
      return;
    }
  }
  assert.fail('Could not find todo item with title: ' + title);
});

When('I click the toggle-all checkbox', function () {
  const toggleAllCheckbox = this.document.querySelector('.toggle-all');
  // happy-dom click does not reliably fire change on checkboxes.
  // Dispatch change directly; the app handler does not read checkbox state.
  toggleAllCheckbox.checked = true;
  const evt = new this.window.Event('change', { bubbles: true });
  toggleAllCheckbox.dispatchEvent(evt);
});

When('I click the {string} button', function (buttonText) {
  if (buttonText === 'Clear completed') {
    const btn = this.document.querySelector('.clear-completed');
    btn.click();
  } else {
    assert.fail('Unknown button: ' + buttonText);
  }
});

When('I view the todo-count', function () {
  // Just a no-op assertion trigger, the count is always visible
});

When('I double-click the label for {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) {
      const evt = new this.window.MouseEvent('dblclick', {
        bubbles: true,
        detail: 2
      });
      label.dispatchEvent(evt);
      return;
    }
  }
  assert.fail('Could not find todo item with title: ' + title);
});

When('I change the edit input value to {string}', function (text) {
  const editInput = this.document.querySelector('.edit');
  editInput.value = text;
  // Dispatch input event
  const evt = new this.window.Event('input', { bubbles: true });
  editInput.dispatchEvent(evt);
});

When('the edit input loses focus', function () {
  const editInput = this.document.querySelector('.edit');
  const evt = new this.window.Event('blur', { bubbles: true });
  editInput.dispatchEvent(evt);
});

When('I navigate to the {string} filter', function (filterName) {
  const filterMap = { 'All': '#/', 'Active': '#/active', 'Completed': '#/completed' };
  const hash = filterMap[filterName];
  assert.ok(hash, 'Unknown filter: ' + filterName);
  this.navigate(hash);
});

When('I reload the app', function () {
  // Preserve localStorage state across reload (new window has its own empty storage)
  const todos = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  const filter = this.localStorage.getItem('todos-vanillajs-filter');
  const extra = {};
  if (filter !== null) extra['todos-vanillajs-filter'] = filter;
  this.loadApp(todos, extra);
});

// -------------------------------------------------------------------------
// Assertion steps (Then)
// -------------------------------------------------------------------------

Then('a todo item with the title {string} appears in the list', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  let found = false;
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) {
      found = true;
      break;
    }
  }
  assert.ok(found, 'Expected todo item "' + title + '" to appear in the list');
});

Then('the new-todo input is cleared', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(input.value, '', 'new-todo input should be cleared');
});

Then('no new todo item is added', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  // The todo-list might be empty if no items
  // Just ensure count hasn't changed from what we expect
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  assert.strictEqual(stored.length, 0, 'No todos should be stored');
});

Then('the {string} todo item has the class {string}', function (title, className) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) {
      assert.ok(items[i].classList.contains(className),
        'Expected "' + title + '" to have class "' + className + '"');
      return;
    }
  }
  assert.fail('Could not find todo item with title: ' + title);
});

Then('the {string} todo item does not have the class {string}', function (title, className) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) {
      assert.ok(!items[i].classList.contains(className),
        'Expected "' + title + '" not to have class "' + className + '"');
      return;
    }
  }
  assert.fail('Could not find todo item with title: ' + title);
});

Then('its toggle checkbox is checked', function () {
  // Use the last toggle that was clicked
  const toggles = this.document.querySelectorAll('.todo-list .toggle');
  let allChecked = true;
  for (let i = 0; i < toggles.length; i++) {
    if (!toggles[i].checked) allChecked = false;
  }
  assert.ok(allChecked, 'toggle should be checked');
});

Then('its toggle checkbox is not checked', function () {
  const toggles = this.document.querySelectorAll('.todo-list .toggle');
  let anyChecked = false;
  for (let i = 0; i < toggles.length; i++) {
    if (toggles[i].checked) anyChecked = true;
  }
  assert.ok(!anyChecked, 'toggle should not be checked');
});

Then('the {string} todo item is removed from the list', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) {
      assert.fail('Expected "' + title + '" to be removed from the list');
    }
  }
  // Also check localStorage
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  for (let i = 0; i < stored.length; i++) {
    if (stored[i].title === title) {
      assert.fail('Expected "' + title + '" to be removed from localStorage');
    }
  }
});

Then('the {string} todo item is replaced by a todo item with the title {string}',
  function (oldTitle, newTitle) {
    const items = this.document.querySelectorAll('.todo-list li');
    let foundOld = false;
    let foundNew = false;
    for (let i = 0; i < items.length; i++) {
      const label = items[i].querySelector('label');
      if (label) {
        if (label.textContent === oldTitle) foundOld = true;
        if (label.textContent === newTitle) foundNew = true;
      }
    }
    assert.ok(!foundOld, 'Old title "' + oldTitle + '" should not appear');
    assert.ok(foundNew, 'New title "' + newTitle + '" should appear');
  });

Then('the {string} todo item still has the title {string}', function (expectedTitle, currentTitle) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === expectedTitle) {
      assert.strictEqual(label.textContent, currentTitle,
        'Title should remain "' + currentTitle + '"');
      return;
    }
  }
  assert.fail('Could not find todo item with title: ' + expectedTitle);
});

Then('all todo items have the class {string}', function (className) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length > 0, 'There should be todo items');
  for (let i = 0; i < items.length; i++) {
    assert.ok(items[i].classList.contains(className),
      'Item ' + i + ' should have class "' + className + '"');
  }
});

Then('no todo items have the class {string}', function (className) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    assert.ok(!items[i].classList.contains(className),
      'Item ' + i + ' should not have class "' + className + '"');
  }
});

Then('the toggle-all checkbox is checked', function () {
  const toggleAll = this.document.querySelector('.toggle-all');
  assert.ok(toggleAll.checked, 'toggle-all should be checked');
});

Then('the toggle-all checkbox is not checked', function () {
  const toggleAll = this.document.querySelector('.toggle-all');
  assert.ok(!toggleAll.checked, 'toggle-all should not be checked');
});

Then('the count shows {string}', function (count) {
  const strong = this.document.querySelector('.todo-count strong');
  assert.ok(strong, 'todo-count strong element should exist');
  assert.strictEqual(strong.textContent, count,
    'Count should be ' + count + ', got ' + strong.textContent);
});

Then('the count text says {string}', function (text) {
  const countEl = this.document.querySelector('.todo-count');
  assert.ok(countEl, 'todo-count element should exist');
  // Check that the text content contains the expected word
  assert.ok(countEl.textContent.indexOf(text) !== -1,
    'Count text should contain "' + text + '", got "' + countEl.textContent + '"');
});

Then('the {string} button is not visible', function (buttonText) {
  if (buttonText === 'Clear completed') {
    const btn = this.document.querySelector('.clear-completed');
    assert.ok(btn, 'clear-completed button should exist');
    assert.strictEqual(btn.style.display, 'none',
      'clear-completed should be hidden');
  } else {
    assert.fail('Unknown button: ' + buttonText);
  }
});

Then('the {string} button is visible', function (buttonText) {
  if (buttonText === 'Clear completed') {
    const btn = this.document.querySelector('.clear-completed');
    assert.ok(btn, 'clear-completed button should exist');
    assert.ok(btn.style.display !== 'none' && btn.style.display !== '',
      'clear-completed should be visible');
  } else {
    assert.fail('Unknown button: ' + buttonText);
  }
});

Then('the section with class {string} is not visible', function (className) {
  const el = this.document.querySelector('.' + className);
  assert.ok(el, 'Element with class "' + className + '" should exist');
  assert.strictEqual(el.style.display, 'none',
    'Element "' + className + '" should be hidden');
});

Then('the section with class {string} is visible', function (className) {
  const el = this.document.querySelector('.' + className);
  assert.ok(el, 'Element with class "' + className + '" should exist');
  assert.ok(el.style.display !== 'none' && el.style.display !== '',
    'Element "' + className + '" should be visible');
});

Then('the footer element is not visible', function () {
  const el = this.document.querySelector('.footer');
  assert.ok(el, 'Footer should exist');
  assert.strictEqual(el.style.display, 'none', 'Footer should be hidden');
});

Then('the footer element is visible', function () {
  const el = this.document.querySelector('.footer');
  assert.ok(el, 'Footer should exist');
  assert.ok(el.style.display !== 'none' && el.style.display !== '',
    'Footer should be visible');
});

Then('the {string} filter link has the class {string}', function (filterName, className) {
  const filterMap = { 'All': '#/', 'Active': '#/active', 'Completed': '#/completed' };
  const href = filterMap[filterName];
  assert.ok(href, 'Unknown filter: ' + filterName);
  const links = this.document.querySelectorAll('.filters a');
  for (let i = 0; i < links.length; i++) {
    if (links[i].getAttribute('href') === href) {
      assert.ok(links[i].classList.contains(className),
        'Filter link "' + filterName + '" should have class "' + className + '"');
      return;
    }
  }
  assert.fail('Could not find filter link with href: ' + href);
});

Then('the {string} filter link does not have the class {string}', function (filterName, className) {
  const filterMap = { 'All': '#/', 'Active': '#/active', 'Completed': '#/completed' };
  const href = filterMap[filterName];
  assert.ok(href, 'Unknown filter: ' + filterName);
  const links = this.document.querySelectorAll('.filters a');
  for (let i = 0; i < links.length; i++) {
    if (links[i].getAttribute('href') === href) {
      assert.ok(!links[i].classList.contains(className),
        'Filter link "' + filterName + '" should not have class "' + className + '"');
      return;
    }
  }
});

Then('I see {int} todo item(s)', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count,
    'Expected ' + count + ' todo items, got ' + items.length);
});

Then('the {string} todo item is not visible', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) {
      assert.ok(items[i].style.display === 'none',
        'Todo "' + title + '" should not be visible');
      return;
    }
  }
  // Not in list at all is also acceptable for "not visible"
});

Then('navigating to the {string} filter shows {int} todo item(s)', function (filterName, count) {
  const filterMap = { 'All': '#/', 'Active': '#/active', 'Completed': '#/completed' };
  const hash = filterMap[filterName];
  this.navigate(hash);
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count,
    'Expected ' + count + ' todo items in ' + filterName + ' filter');
});

// -------------------------------------------------------------------------
// Persistence steps
// -------------------------------------------------------------------------

Then('localStorage has a key matching {string}', function (pattern) {
  const keys = Object.keys(this.localStorage);
  let found = false;
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].indexOf('todos-') === 0) {
      found = true;
      break;
    }
  }
  assert.ok(found, 'localStorage should have a key starting with "todos-"');
});

Then('the stored value is a non-empty JSON array', function () {
  const stored = this.localStorage.getItem('todos-vanillajs');
  assert.ok(stored, 'localStorage should have a stored value');
  const parsed = JSON.parse(stored);
  assert.ok(Array.isArray(parsed), 'Stored value should be an array');
  assert.ok(parsed.length > 0, 'Stored array should not be empty');
});

Then('the first stored todo has a title {string}', function (title) {
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs'));
  assert.ok(stored.length > 0, 'Should have stored todos');
  assert.strictEqual(stored[0].title, title,
    'First stored todo title should be "' + title + '"');
});

Then('the first stored todo is not completed', function () {
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs'));
  assert.ok(stored.length > 0, 'Should have stored todos');
  assert.strictEqual(stored[0].completed, false,
    'First stored todo should not be completed');
});

Then('the first stored todo has an id', function () {
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs'));
  assert.ok(stored.length > 0, 'Should have stored todos');
  assert.ok(stored[0].id !== undefined && stored[0].id !== null,
    'First stored todo should have an id');
});

Then('the stored todo with title {string} is completed', function (title) {
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  for (let i = 0; i < stored.length; i++) {
    if (stored[i].title === title) {
      assert.strictEqual(stored[i].completed, true,
        'Stored todo "' + title + '" should be completed');
      return;
    }
  }
  assert.fail('Could not find stored todo with title: ' + title);
});

Then('the stored todos array is empty', function () {
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  assert.strictEqual(stored.length, 0, 'Stored todos should be empty');
});

Then('the stored todo with title {string} exists', function (title) {
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  for (let i = 0; i < stored.length; i++) {
    if (stored[i].title === title) {
      return;
    }
  }
  assert.fail('Could not find stored todo with title: ' + title);
});

Then('the first todo item has the title {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length >= 1, 'At least 1 todo item should exist');
  const label = items[0].querySelector('label');
  assert.ok(label, 'First item should have a label');
  assert.strictEqual(label.textContent, title,
    'First todo should have title "' + title + '"');
});

Then('the second todo item has the title {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length >= 2, 'At least 2 todo items should exist');
  const label = items[1].querySelector('label');
  assert.ok(label, 'Second item should have a label');
  assert.strictEqual(label.textContent, title,
    'Second todo should have title "' + title + '"');
});

Then('there is no stored todo with title {string}', function (title) {
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  for (let i = 0; i < stored.length; i++) {
    if (stored[i].title === title) {
      assert.fail('Found unexpected stored todo with title: ' + title);
    }
  }
});

Then('I see the list filtered to completed todos', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === 'Task A') {
      assert.fail('Completed todos only should be visible, active items hidden');
    }
  }
  // All visible items should be completed
  for (let i = 0; i < items.length; i++) {
    assert.ok(items[i].classList.contains('completed'),
      'Visible item should be completed');
  }
});

// -------------------------------------------------------------------------
// "the {string} todo item remains in the list" (And step after clear completed)
// -------------------------------------------------------------------------

Then('the {string} todo item remains in the list', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  let found = false;
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) {
      found = true;
      break;
    }
  }
  assert.ok(found, 'Expected "' + title + '" to remain in the list');
});

(function () {
  'use strict';

  var STORAGE_KEY = 'todos-vanillajs';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  var todos = [];
  var filter = 'all';

  // --- Model / localStorage ---

  /** @planks("localStorage has a key matching {string}") @planks("the stored value is a non-empty JSON array") @planks("the first stored todo has a title {string}") @planks("the first stored todo is not completed") @planks("the first stored todo has an id") @planks("the stored todo with title {string} is completed") @planks("the stored todos array is empty") @planks("the stored todo with title {string} exists") @planks("there is no stored todo with title {string}") @planks("the first todo item has the title {string}") @planks("the second todo item has the title {string}") @planks("the stored todos array is empty") */
  function loadTodos() {
    try {
      todos = JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      todos = [];
    }
  }

  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function generateId() {
    return Date.now() + Math.random().toString(36).substr(2, 9);
  }

  // --- Filter helpers ---

  /** @planks("the {string} filter link has the class {string}") @planks("the {string} filter link does not have the class {string}") @planks("navigating to the {string} filter shows {int} todo item(s)") */
  function getFilter() {
    var hash = window.location.hash || '';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  function getFilteredTodos() {
    var f = getFilter();
    if (f === 'active') return todos.filter(function (t) { return !t.completed; });
    if (f === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  function getActiveCount() {
    return todos.filter(function (t) { return !t.completed; }).length;
  }

  function getCompletedCount() {
    return todos.filter(function (t) { return t.completed; }).length;
  }

  // --- Render ---

  var todoApp = document.querySelector('.todoapp');
  var mainSection = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var todoList = document.querySelector('.todo-list');
  var newTodoInput = document.querySelector('.new-todo');
  var toggleAllCheckbox = document.querySelector('.toggle-all');
  var todoCount = document.querySelector('.todo-count');
  var clearCompleted = document.querySelector('.clear-completed');
  var filterLinks = document.querySelectorAll('.filters a');

  /** @planks("the section with class {string} is not visible") @planks("the section with class {string} is visible") @planks("the footer element is not visible") @planks("the footer element is visible") @planks("the count shows {string}") @planks("the count text says {string}") @planks("the {string} filter link has the class {string}") @planks("the {string} filter link does not have the class {string}") @planks("I see {int} todo item") @planks("the {string} todo item is not visible") */
  function render() {
    var filtered = getFilteredTodos();
    var activeCount = getActiveCount();
    var completedCount = getCompletedCount();

    // Main and footer visibility
    if (todos.length === 0) {
      mainSection.style.display = 'none';
      footer.style.display = 'none';
    } else {
      mainSection.style.display = 'block';
      footer.style.display = 'block';
    }

    // Toggle-all state
    toggleAllCheckbox.checked = activeCount === 0 && todos.length > 0;

    // Generate list items
    var html = '';
    for (var i = 0; i < filtered.length; i++) {
      var todo = filtered[i];
      var liClass = '';
      if (todo.completed) liClass += ' completed';
      var checkedAttr = todo.completed ? 'checked' : '';
      html += '<li data-id="' + todo.id + '" class="' + liClass + '">';
      html += '<div class="view">';
      html += '<input class="toggle" type="checkbox" ' + checkedAttr + '>';
      html += '<label>' + escapeHtml(todo.title) + '</label>';
      html += '<button class="destroy"></button>';
      html += '</div>';
      html += '<input class="edit" value="' + escapeHtml(todo.title) + '">';
      html += '</li>';
    }
    todoList.innerHTML = html;

    // Update count
    var word = activeCount === 1 ? 'item' : 'items';
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + word + ' left';

    // Clear completed visibility
    if (completedCount === 0) {
      clearCompleted.style.display = 'none';
    } else {
      clearCompleted.style.display = 'block';
    }

    // Filter link selected state
    var currentFilter = getFilter();
    for (var j = 0; j < filterLinks.length; j++) {
      var link = filterLinks[j];
      var href = link.getAttribute('href');
      if (href === '#/' && currentFilter === 'all') {
        link.className = 'selected';
      } else if (href === '#/active' && currentFilter === 'active') {
        link.className = 'selected';
      } else if (href === '#/completed' && currentFilter === 'completed') {
        link.className = 'selected';
      } else {
        link.className = '';
      }
    }

    // Save filter state
    localStorage.setItem(STORAGE_KEY + '-filter', currentFilter);
  }

  function escapeHtml(str) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(str));
    return div.innerHTML;
  }

  // --- Actions ---

  /** @planks("a todo item with the title {string} appears in the list") @planks("the new-todo input is cleared") @planks("no new todo item is added") @planks("the count shows {string}") @planks("the count text says {string}") @planks("Todos are persisted to localStorage on creation") */
  function addTodo(title) {
    var trimmed = title.trim();
    if (trimmed === '') return;
    todos.push({
      id: generateId(),
      title: trimmed,
      completed: false
    });
    saveTodos();
    render();
  }

  /** @planks("the {string} todo item has the class {string}") @planks("the {string} todo item does not have the class {string}") @planks("its toggle checkbox is checked") @planks("its toggle checkbox is not checked") @planks("the stored todo with title {string} is completed") */
  function toggleTodo(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].completed = !todos[i].completed;
        break;
      }
    }
    saveTodos();
    render();
  }

  /** @planks("the {string} todo item is removed from the list") @planks("the stored todos array is empty") */
  function deleteTodo(id) {
    var newTodos = [];
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id !== id) {
        newTodos.push(todos[i]);
      }
    }
    todos = newTodos;
    saveTodos();
    render();
  }

  /** @planks("the {string} todo item is replaced by a todo item with the title {string}") @planks("the {string} todo item still has the title {string}") @planks("the stored todo with title {string} exists") @planks("there is no stored todo with title {string}") */
  function updateTodo(id, title) {
    var trimmed = title.trim();
    if (trimmed === '') {
      deleteTodo(id);
      return;
    }
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].title = trimmed;
        break;
      }
    }
    saveTodos();
    render();
  }

  /** @planks("all todo items have the class {string}") @planks("no todo items have the class {string}") @planks("the toggle-all checkbox is checked") @planks("the toggle-all checkbox is not checked") */
  function toggleAll() {
    var activeCount = getActiveCount();
    var allDone = activeCount === 0;
    for (var i = 0; i < todos.length; i++) {
      todos[i].completed = !allDone;
    }
    saveTodos();
    render();
  }

  /** @planks("the {string} button is not visible") @planks("the {string} button is visible") @planks("the {string} todo item remains in the list") */
  function clearCompletedTodos() {
    var newTodos = [];
    for (var i = 0; i < todos.length; i++) {
      if (!todos[i].completed) {
        newTodos.push(todos[i]);
      }
    }
    todos = newTodos;
    saveTodos();
    render();
  }

  // --- Event handlers ---

  function handleNewTodoKeydown(e) {
    if (e.keyCode === ENTER_KEY) {
      addTodo(newTodoInput.value);
      newTodoInput.value = '';
    }
  }

  function handleTodoListClick(e) {
    var target = e.target;
    var li = target.closest ? target.closest('li') : null;
    if (!li) return;
    var id = li.getAttribute('data-id');

    if (target.className === 'toggle') {
      toggleTodo(id);
    } else if (target.className === 'destroy') {
      deleteTodo(id);
    }
  }

  function handleTodoListDblclick(e) {
    var target = e.target;
    if (target.tagName !== 'LABEL') return;
    var li = target.closest ? target.closest('li') : null;
    if (!li) return;

    // Put li in editing mode
    li.className = li.className + ' editing';
    var editInput = li.querySelector('.edit');
    editInput.value = editInput.value;
    editInput.focus();
    // Select text
    editInput.selectionStart = editInput.selectionEnd = editInput.value.length;
  }

  function handleEditKeydown(e) {
    var target = e.target;
    if (target.className !== 'edit') return;
    var li = target.closest ? target.closest('li') : null;
    if (!li) return;
    var id = li.getAttribute('data-id');

    if (e.keyCode === ENTER_KEY) {
      updateTodo(id, target.value);
    } else if (e.keyCode === ESCAPE_KEY) {
      // Cancel, restore title
      for (var i = 0; i < todos.length; i++) {
        if (todos[i].id === id) {
          target.value = todos[i].title;
          break;
        }
      }
      li.className = li.className.replace(/\s*editing/g, '');
    }
  }

  function handleEditBlur(e) {
    var target = e.target;
    if (target.className !== 'edit') return;
    var li = target.closest ? target.closest('li') : null;
    if (!li) return;
    var id = li.getAttribute('data-id');

    // Save on blur if not already handled by keydown
    if (li.className.indexOf('editing') !== -1) {
      updateTodo(id, target.value);
    }
  }

  function handleToggleAllChange(e) {
    toggleAll();
  }

  function handleClearCompletedClick(e) {
    clearCompletedTodos();
  }

  // --- Filter persistence ---

  function restoreFilter() {
    var saved = localStorage.getItem(STORAGE_KEY + '-filter');
    if (saved === 'active' || saved === 'completed') {
      window.location.hash = '#/' + saved;
    } else {
      window.location.hash = '#/';
    }
  }

  // --- Hash change handler ---

  function handleHashChange() {
    render();
  }

  // --- Init ---

  function init() {
    loadTodos();
    restoreFilter();
    render();

    newTodoInput.addEventListener('keydown', handleNewTodoKeydown);
    todoList.addEventListener('click', handleTodoListClick);
    todoList.addEventListener('dblclick', handleTodoListDblclick);
    todoList.addEventListener('keydown', handleEditKeydown);
    todoList.addEventListener('blur', handleEditBlur, true);
    toggleAllCheckbox.addEventListener('change', handleToggleAllChange);
    clearCompleted.addEventListener('click', handleClearCompletedClick);
    window.addEventListener('hashchange', handleHashChange);
  }

  init();
})();

#!/usr/bin/env node
// Plank-join checker for Shipshape.
// Scans implementation directories for @planks(...) and @planks-provisional(...)
// annotations, reads step definitions from features/support, and reports the join.
// Exits non-zero when a behaviour-bearing seam has no plank, a plank matches no
// pattern, or a provisional plank names a scenario that lost its @captain tag.

import { promises as fs } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(fileURLToPath(import.meta.url), '..', '..');
const IMPLEMENTATION_DIRS = ['.', 'js', 'css'];
const SUPPORT_DIRS = ['features/support'];
const SPECS_DIR = 'features';

// --- Helpers ---

async function* walkFiles(dir, depth = 0) {
  if (depth > 6) return;
  let entries;
  try {
    entries = await fs.readdir(dir, { withFileTypes: true });
  } catch {
    return;
  }
  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
    if (entry.isDirectory()) {
      yield* walkFiles(fullPath, depth + 1);
    } else if (entry.isFile()) {
      yield fullPath;
    }
  }
}

// Extract @planks("...") and @planks-provisional("...") from file content.
// Also catches bare planks outside docblocks via token search.
function extractPlanks(content, filePath) {
  const planks = [];
  const provisional = [];

  // Match docblock annotations
  const docblockRe = /\/\*\*[\s\S]*?\*\//g;
  let match;
  while ((match = docblockRe.exec(content)) !== null) {
    const block = match[0];
    // @planks("pattern")
    let pm = block.match(/@planks\(\s*"([^"]+)"\s*\)/);
    if (pm) planks.push({ pattern: pm[1], location: `${filePath}:docblock` });
    // @planks-provisional("ref")
    let ppm = block.match(/@planks-provisional\(\s*"([^"]+)"\s*\)/);
    if (ppm) provisional.push({ scenario: ppm[1], location: `${filePath}:docblock` });
  }

  // Token search for planks outside docblocks (line comments, inline)
  const lines = content.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    // Skip docblock lines
    if (line.trimStart().startsWith('*') || line.trimStart().startsWith('/**')) continue;
    // @planks("...")
    let pm = line.match(/@planks\(\s*"([^"]+)"\s*\)/);
    if (pm) {
      const isInDocblock = content.indexOf('/**') !== -1 && content.lastIndexOf('*/', content.indexOf(line)) > content.indexOf('/**', Math.max(0, content.indexOf(line) - 1000));
      if (!isInDocblock) planks.push({ pattern: pm[1], location: `${filePath}:${i + 1}:token` });
    }
    // @planks-provisional("...")
    let ppm = line.match(/@planks-provisional\(\s*"([^"]+)"\s*\)/);
    if (ppm) {
      const isInDocblock = content.indexOf('/**') !== -1 && content.lastIndexOf('*/', content.indexOf(line)) > content.indexOf('/**', Math.max(0, content.indexOf(line) - 1000));
      if (!isInDocblock) provisional.push({ scenario: ppm[1], location: `${filePath}:${i + 1}:token` });
    }
  }

  return { planks, provisional };
}

// Extract step definition patterns from support files.
function extractStepPatterns(content, filePath) {
  const patterns = [];

  // Cucumber-js step definitions: Given/When/Then(pattern, ...)
  const stepRe = /(?:Given|When|Then|And|But)\(\s*((['"`])((?:\\\2|(?!\2).)*?)\2)\s*,/g;
  let match;
  while ((match = stepRe.exec(content)) !== null) {
    patterns.push({ pattern: match[3], location: filePath, keyword: match[0].split('(')[0] });
  }

  // Also match regex patterns: /pattern/
  const regexRe = /(?:Given|When|Then|And|But)\(\s*\/((?:\\\/|[^\/])*)\/\s*,/g;
  while ((match = regexRe.exec(content)) !== null) {
    patterns.push({ pattern: match[1], location: filePath, keyword: match[0].split('(')[0], isRegex: true });
  }

  return patterns;
}

// Extract @captain scenario names from feature files.
async function extractCaptainScenarios() {
  const captainScenarios = new Set();
  const specsDir = path.join(ROOT, SPECS_DIR);

  for await (const filePath of walkFiles(specsDir)) {
    if (!filePath.endsWith('.feature')) continue;
    const content = await fs.readFile(filePath, 'utf8');
    const relPath = path.relative(ROOT, filePath);
    const lines = content.split('\n');

    // Tag-based approach: find scenarios tagged @captain
    let currentTags = [];
    let inScenario = false;
    let scenarioName = '';

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i].trim();
      if (line.startsWith('@')) {
        // Accumulate tags
        for (const tag of line.split(/\s+/)) {
          if (tag.startsWith('@')) currentTags.push(tag);
        }
        continue;
      }
      if (line.startsWith('Scenario Outline') || line.startsWith('Scenario:')) {
        scenarioName = line.replace(/^(Scenario Outline|Scenario):\s*/, '').trim();
        inScenario = true;
        if (currentTags.includes('@captain')) {
          captainScenarios.add(`${relPath}:${scenarioName}`);
        }
        currentTags = [];
        continue;
      }
      if (line.startsWith('Feature:') || line.startsWith('Background:') || line.startsWith('Rule:')) {
        currentTags = [];
        inScenario = false;
      }
      if (line === '' || line.startsWith('#')) continue;
    }
  }

  return captainScenarios;
}

// --- Main ---

async function main() {
  let exitCode = 0;
  const allPlanks = [];
  const allProvisional = [];
  const allPatterns = [];

  // 1. Scan implementation directories for planks
  for (const implDir of IMPLEMENTATION_DIRS) {
    const absDir = path.join(ROOT, implDir);
    try {
      await fs.access(absDir);
    } catch {
      continue; // directory doesn't exist yet (greenfield)
    }
    for await (const filePath of walkFiles(absDir)) {
      const ext = path.extname(filePath);
      if (!['.js', '.html', '.css', '.mjs', '.cjs', '.json'].includes(ext)) continue;
      const content = await fs.readFile(filePath, 'utf8');
      const relPath = path.relative(ROOT, filePath);
      const { planks, provisional } = extractPlanks(content, relPath);
      allPlanks.push(...planks);
      allProvisional.push(...provisional);
    }
  }

  // 2. Scan support directories for step definition patterns
  for (const supportDir of SUPPORT_DIRS) {
    const absDir = path.join(ROOT, supportDir);
    try {
      await fs.access(absDir);
    } catch {
      continue;
    }
    for await (const filePath of walkFiles(absDir)) {
      if (!filePath.endsWith('.js') && !filePath.endsWith('.mjs') && !filePath.endsWith('.cjs')) continue;
      const content = await fs.readFile(filePath, 'utf8');
      const relPath = path.relative(ROOT, filePath);
      const patterns = extractStepPatterns(content, relPath);
      allPatterns.push(...patterns);
    }
  }

  // 3. Read @captain scenarios from specs
  let captainScenarios;
  try {
    captainScenarios = await extractCaptainScenarios();
  } catch {
    captainScenarios = new Set();
  }

  // 4. Report the join
  console.log('PLANK JOIN REPORT');
  console.log('=================');

  // Report planks
  console.log('\n@planks annotations:');
  if (allPlanks.length === 0) {
    console.log('  (none)');
  } else {
    for (const plank of allPlanks) {
      const matched = allPatterns.some(p => p.pattern === plank.pattern);
      console.log(`  [${matched ? 'OK' : 'STALE'}] "${plank.pattern}" @ ${plank.location}`);
      if (!matched) exitCode = 1;
    }
  }

  // Report provisional planks
  console.log('\n@planks-provisional annotations:');
  if (allProvisional.length === 0) {
    console.log('  (none)');
  } else {
    for (const plank of allProvisional) {
      const stillCaptain = captainScenarios.has(plank.scenario);
      console.log(`  [${stillCaptain ? 'OK' : 'PROMOTED_OR_MISSING'}] "${plank.scenario}" @ ${plank.location}`);
      if (!stillCaptain) exitCode = 1;
    }
  }

  // Report patterns without planks
  console.log('\nStep patterns without matching planks:');
  const patternsWithoutPlanks = allPatterns.filter(p =>
    !allPlanks.some(pl => pl.pattern === p.pattern)
  );
  if (patternsWithoutPlanks.length === 0) {
    console.log('  (none)');
  } else {
    for (const p of patternsWithoutPlanks) {
      console.log(`  [UNPLANKED] "${p.pattern}" @ ${p.location}`);
      exitCode = 1;
    }
  }

  // Summary
  console.log(`\nSummary: ${allPlanks.length} @planks, ${allProvisional.length} @planks-provisional, ${allPatterns.length} step patterns`);

  process.exit(exitCode);
}

main().catch(err => {
  console.error('plank-join error:', err);
  process.exit(2);
});

// Verification-conformance rule set for Shipshape.
// Plain text-pattern rules checked through Node runtime.
// Two required plank rules: plank-form and plank-coverage.
// These compensate for the absence of a docblock reader-backed checker.

const RULES = {
  // Rule: A @planks token must appear in a docblock immediately preceding a declaration.
  // Catches line-comment planks and in-body planks.
  "plank-form": {
    description: "@planks token must be in a docblock on a declaration, not a line comment or inline",
    check: (content, filePath) => {
      const violations = [];
      const lines = content.split('\n');
      for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        // Skip docblock lines
        if (line.trimStart().startsWith('*') || line.trimStart().startsWith('/**')) continue;
        if (line.includes('@planks(') || line.includes('@planks-provisional(')) {
          // Check if this line is inside a docblock
          const beforeThis = lines.slice(0, i + 1).join('\n');
          const lastOpen = beforeThis.lastIndexOf('/**');
          const lastClose = beforeThis.lastIndexOf('*/');
          if (lastOpen === -1 || lastClose > lastOpen) {
            violations.push({ line: i + 1, text: line.trim(), file: filePath });
          }
        }
      }
      return violations;
    }
  },

  // Rule: A @planks pattern must match a current step-definition pattern.
  // Note: full cross-reference requires reading all support files; see plank-join.mjs.
  // This rule catches planks that are textually stale (e.g. leading Given/When/Then).
  "plank-pattern-form": {
    description: "@planks string must not carry a leading Given, When, Then, And, or But keyword",
    check: (content, filePath) => {
      const violations = [];
      const lineRe = /@planks\(\s*"(Given|When|Then|And|But)\s+(.+?)"\s*\)/g;
      let match;
      while ((match = lineRe.exec(content)) !== null) {
        const lineNum = content.substring(0, match.index).split('\n').length;
        violations.push({ line: lineNum, text: match[0], file: filePath, detail: `Carries leading "${match[1]}" keyword` });
      }
      // Check @planks-provisional too
      const provRe = /@planks-provisional\(\s*"(.+?)"\s*\)/g;
      while ((match = provRe.exec(content)) !== null) {
        const ref = match[1];
        // Must be in repo-root-relative form: spec.feature:Scenario Name
        if (!ref.includes('.feature:')) {
